// Some portions generated by Claude
/** SPARQL generated from the filters: repository-wide value counts and the "visual query" of the current selection. */
import { TYPE_FACET_ID } from "./graph-facets.ts";
import { intrinsicFacetSparqlFilter } from "./graph-filters.ts";
import { isSafeSparqlIri } from "./graph-terms.ts";
import { UNTYPED_IRI_TYPE } from "./graph-visuals.ts";
import { sparqlFacetValueToken } from "./rdf-terms.ts";
import { scoped, type GraphScope } from "./rdf-vocabulary.ts";

/** How many of the sources have each value of the predicate in the repository, with the values' labels. */
export function facetCountQuery(
  sourceIds: string[],
  predicate: string,
  scope: GraphScope = "default",
  languages: readonly string[] = ["en"],
) {
  const values = sourceIds
    .filter(isSafeSparqlIri)
    .slice(0, 120)
    .map((sourceId) => `<${sourceId}>`)
    .join(" ");
  const relation =
    predicate === TYPE_FACET_ID
      ? "<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>"
      : `<${predicate}>`;
  const language = languages.find((tag) => /^[A-Za-z]{1,8}(-[A-Za-z0-9]{1,8})*$/.test(tag) && tag !== "und") ?? "en";
  return `PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?value ?valueLabel (COUNT(DISTINCT ?source) AS ?count) WHERE {
  VALUES ?source { ${values} }
  ${scoped(`?source ${relation} ?value .`, scope)}
  OPTIONAL {
    ?value rdfs:label ?valueLabel .
    FILTER(LANG(?valueLabel) = "" || LANGMATCHES(LANG(?valueLabel), "${language}"))
  }
}
GROUP BY ?value ?valueLabel
ORDER BY DESC(?count)
LIMIT 100`;
}

export type QueryRange = { kind: "number" | "date"; from: string; to: string };

/** A range filter as SPARQL: numbers compare numerically, dates by their ISO day (so date and dateTime both work). */
export function rangeSparqlFilter(variable: string, range: QueryRange) {
  const valid = (text: string) =>
    range.kind === "number" ? /^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(text) : /^\d{4}-\d{2}-\d{2}$/.test(text);
  const from = range.from.trim();
  const to = range.to.trim();
  const tests =
    range.kind === "number"
      ? [valid(from) ? `${variable} >= ${from}` : "", valid(to) ? `${variable} <= ${to}` : ""]
      : [
          valid(from) ? `SUBSTR(STR(${variable}), 1, 10) >= "${from}"` : "",
          valid(to) ? `SUBSTR(STR(${variable}), 1, 10) <= "${to}"` : "",
        ];
  const conditions = tests.filter(Boolean);
  return conditions.length ? `FILTER(${conditions.join(" && ")})` : null;
}

export function formatRangeValue(kind: "number" | "date", value: number) {
  if (kind === "date") return new Date(value).toISOString().slice(0, 10);
  return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(6)));
}

export function generatedFacetQuery(
  selectedFacetValues: Map<string, Set<string>>,
  options: { wikidata: boolean; ranges?: ReadonlyMap<string, QueryRange> },
) {
  const activeFacets = [...selectedFacetValues.entries()].filter(
    ([, values]) => values.size > 0,
  );
  const lines = [
    `${activeFacets.length ? "SELECT DISTINCT" : "SELECT"} ?source ?predicate ?target WHERE {`,
    "  ?source ?predicate ?target .",
  ];
  if (activeFacets.length) {
    lines.push(
      "  { BIND(?source AS ?focus) } UNION { BIND(?target AS ?focus) }",
    );
  }
  let index = 0;
  activeFacets.forEach(([facetId, values]) => {
    const intrinsicFilter = intrinsicFacetSparqlFilter(
      facetId,
      values,
    );
    if (intrinsicFilter) {
      lines.push(`  ${intrinsicFilter}`);
      return;
    }
    const relation =
      facetId === TYPE_FACET_ID
        ? options.wikidata
          ? "<http://www.wikidata.org/prop/direct/P31>"
          : "<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>"
        : `<${facetId}>`;
    if (facetId === TYPE_FACET_ID) {
      const untypedSelected = values.has(UNTYPED_IRI_TYPE.id);
      const typedTokens = [...values]
        .filter((value) => value !== UNTYPED_IRI_TYPE.id)
        .map(sparqlFacetValueToken)
        .filter((value): value is string => Boolean(value));
      const typedVariable = `?facetTypeValue${index}`;
      const typedMatch = typedTokens.length
        ? `EXISTS { ?focus ${relation} ${typedVariable} . VALUES ${typedVariable} { ${typedTokens.join(" ")} } }`
        : "false";
      const untypedMatch = untypedSelected
        ? `isIRI(?focus) && NOT EXISTS { ?focus ${relation} ?anyType }`
        : "false";
      lines.push(`  FILTER(${untypedMatch} || ${typedMatch})`);
      index += 1;
      return;
    }
    const variable = `?facetValue${index}`;
    lines.push(`  ?focus ${relation} ${variable} .`);
    const range = options.ranges?.get(facetId);
    const rangeFilter = range ? rangeSparqlFilter(variable, range) : null;
    if (rangeFilter) {
      lines.push(`  ${rangeFilter}`);
      index += 1;
      return;
    }
    const tokens = [...values]
      .map(sparqlFacetValueToken)
      .filter((value): value is string => Boolean(value));
    if (!tokens.length) {
      lines.push("  FILTER(false)");
      index += 1;
      return;
    }
    lines.push(
      `  VALUES ${variable} { ${tokens.join(" ")} }`,
    );
    index += 1;
  });
  lines.push("}", "LIMIT 300");
  return lines.join("\n");
}
